// Code node "Rows to enrich". Rows with a LinkedIn URL and no status yet, at most MAX_ROWS per run.
const MAX_ROWS = 10;
const out = [];
for (const { json: r } of $input.all()) {
  const url = String(r.linkedin_url || "").trim();
  if (!/linkedin\.com\/in\//i.test(url) || String(r.status || "").trim()) continue;
  out.push({ json: { row_number: r.row_number, linkedin_url: url.split("?")[0], company_domain: String(r.company_domain || "").trim().toLowerCase() } });
  if (out.length >= MAX_ROWS) break;
}
return out;

// Code node "Row to write". Pairs each agent answer with its sheet row and adds what it cost.
// Shared helper: adds up what the agent's looot calls cost, from the agent's intermediate steps
// (the agent's "Return Intermediate Steps" option is on). Each looot tool answer carries actualCost.
function agentCost(item) {
  const steps = (item && Array.isArray(item.intermediateSteps)) ? item.intermediateSteps : [];
  let usd = 0;
  let calls = 0;
  for (const step of steps) {
    const tool = String((step && step.action && step.action.tool) || "");
    if (!/looot/i.test(tool)) continue;
    calls += 1;
    const text = typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation ?? "");
    for (const m of text.matchAll(/"actualCost"\s*:\s*([0-9.eE+-]+)/g)) {
      const n = Number(m[1]);
      if (Number.isFinite(n)) usd += n;
    }
  }
  return { looot_calls: calls, looot_cost_usd: Number(usd.toFixed(6)) };
}

const rows = $("Rows to enrich").all().map((i) => i.json);
return $input.all().map(({ json: item }, i) => {
  const o = (item.output && typeof item.output === "object") ? item.output : {};
  const cost = agentCost(item);
  return {
    json: {
      row_number: rows[i] ? rows[i].row_number : null,
      full_name: o.full_name || "",
      title: o.title || "",
      company: o.company || "",
      email: String(o.email || "").toLowerCase(),
      email_status: o.email ? (o.email_status || "unknown") : "not_found",
      message: String(o.message || "").slice(0, 600),
      status: o.full_name ? "done" : "no_profile",
      looot_cost_usd: cost.looot_cost_usd,
      checked_at: new Date().toISOString(),
    },
  };
});
